/// 把名字拼成一句问候语。
fn greet(name: &str) -> String {
    format!("你好，{}！欢迎来到 Rust。", name)
}

fn main() {
    println!("{}", greet("Guo"));
    println!("Hello, world!");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn greet_contains_name() {
        let s = greet("Guo");
        assert!(s.contains("Guo"));
    }

    #[test]
    fn greet_ends_with_rust() {
        assert!(greet("Guo").ends_with("Rust。"));
    }
}

fn takes_and_returns(s: String) -> String {
    println!("函数里拿到：{}", s);
    s
}

fn main() {
    let x = 42;
    let y = x;
    println!("Copy: x = {}, y = {}", x, y);

    let s1 = String::from("hello");
    let s2 = s1;
    // println!("{}", s1); // 取消注释会报 E0382：s1 已被 move
    println!("move 后：s2 = {}", s2);

    let s3 = String::from("hello");
    let s4 = s3.clone();
    println!("clone 后：s3 = {}, s4 = {}", s3, s4);

    let s5 = String::from("world");
    let s6 = takes_and_returns(s5);
    println!("拿回所有权后：s6 = {}", s6);

    {
        let s7 = String::from("临时");
        println!("作用域内：{}", s7);
    }
    println!("作用域已结束，s7 不可用（也不用 free）");
}
